<template>
  <F7Page
    class="messenger-thread"
    infinite
    infinite-top
    :infinite-preloader="loadingOlder"
    :infinite-distance="80"
    @infinite="handleLoadOlder"
    @page:beforein="hideTabbar"
    @page:beforeout="showTabbar"
  >
    <F7Navbar back-link="Back">
      <template #title>
        <div class="flex items-center gap-2.5">
          <MessengerChannelAvatar
            v-if="header"
            compact
            :name="header.name"
            :image-url="header.avatarUrl"
            :channel-type="header.channelType"
            :online="header.online"
          />
          <div class="flex flex-col leading-tight">
            <span class="text-[15px] font-[760] text-[#090e24]">{{
              header?.name ?? "Conversation"
            }}</span>
            <span class="text-[11px] font-medium text-[#657096]">{{ subtitle }}</span>
          </div>
        </div>
      </template>
    </F7Navbar>

    <F7Messagebar
      :placeholder="placeholder"
      :value="text"
      :attachments-visible="picked.length > 0"
      @input="onInput"
      @keydown="onKeydown"
    >
      <template #inner-start>
        <F7Link icon-only @click="openPicker">
          <span class="flex h-9 w-9 items-center justify-center text-[#657096]">
            <ILucideImage class="h-[22px] w-[22px]" />
          </span>
        </F7Link>
      </template>
      <template #inner-end>
        <F7Link
          :class="canSend ? 'opacity-100' : 'pointer-events-none opacity-40'"
          icon-only
          @click="submit"
        >
          <span
            class="flex h-9 w-9 items-center justify-center rounded-full bg-[#1f6df5] text-white"
          >
            <ILucideArrowUp class="h-[18px] w-[18px]" />
          </span>
        </F7Link>
      </template>
      <F7MessagebarAttachments>
        <F7MessagebarAttachment
          v-for="image in picked"
          :key="image.id"
          :image="image.dataUrl"
          @attachment:delete="removeAttachment(image.id)"
        />
      </F7MessagebarAttachments>
    </F7Messagebar>

    <F7Messages>
      <p v-if="!loading && !items.length" class="px-6 py-10 text-center text-[13px] text-[#657096]">
        No messages yet. Say hello.
      </p>

      <template v-for="item in items" :key="item.key">
        <F7MessagesTitle v-if="item.kind === 'title'">
          <b>{{ item.label }}</b>
        </F7MessagesTitle>
        <F7Message
          v-else-if="item.variant === 'image'"
          :type="item.message.isMine ? 'sent' : 'received'"
          :name="receivedName(item)"
          :first="item.first"
          :last="item.last"
          :tail="item.tail"
          :text-footer="item.showFooter ? footer(item) : undefined"
        >
          <template #image>
            <img
              :src="imageUrl(item.attachment)"
              loading="lazy"
              class="max-w-[220px] cursor-pointer rounded-xl object-cover"
              @click="openPhoto(imageUrl(item.attachment))"
            />
          </template>
        </F7Message>
        <F7Message
          v-else
          :type="item.message.isMine ? 'sent' : 'received'"
          :name="receivedName(item)"
          :first="item.first"
          :last="item.last"
          :tail="item.tail"
          :text="bodyText(item.message.body)"
          :text-footer="item.showFooter ? footer(item) : undefined"
        />
      </template>

      <F7Message
        v-if="header?.isTyping"
        type="received"
        :typing="true"
        :name="header.typingName ?? undefined"
        :first="true"
        :last="true"
        :tail="true"
      />
    </F7Messages>

    <input
      ref="fileInput"
      type="file"
      accept="image/*"
      multiple
      class="hidden"
      @change="onFilesPicked"
    />
  </F7Page>
</template>

<script setup lang="ts">
import { computed, nextTick, ref } from "vue";
import { f7 } from "framework7-vue";
import type { Router } from "framework7/types";
import type { ThreadAttachment } from "@aybsig/messenger";
import { useTabbarVisibility } from "../../../shared/composables/useTabbarVisibility";
import { useServerStore } from "@/shared/stores/server.store";
import { useMessengerThread } from "@aybsig/messenger/vue";
import MessengerChannelAvatar from "../components/MessengerChannelAvatar.vue";
import { useMessengerComposer } from "../composables/useMessengerComposer";
import {
  buildThreadItems,
  formatMessageTime,
  messageBodyToText,
  type ThreadRenderItem,
} from "../messenger.thread";

const { tabbarHidden } = useTabbarVisibility();
const serverStore = useServerStore();

const props = defineProps<{ f7route: Router.Route }>();

const channelId = Number(props.f7route.params.channelId);

const { messages, header, loading, loadingOlder, sending, hasMore, send, loadOlder, setTyping } =
  useMessengerThread(channelId);

const fileInput = ref<HTMLInputElement | null>(null);
const { text, picked, placeholder, canSend, addFiles, removeAttachment, submit } =
  useMessengerComposer(send, () => sending.value);

function onInput(event: Event) {
  text.value = (event.target as HTMLInputElement | HTMLTextAreaElement).value;
  if (text.value.trim()) setTyping();
}

function onKeydown(event: KeyboardEvent) {
  if (event.key !== "Enter" || event.shiftKey) return;
  event.preventDefault();
  void submit();
}

function openPicker() {
  fileInput.value?.click();
}

async function onFilesPicked(event: Event) {
  const input = event.target as HTMLInputElement;
  if (input.files) await addFiles(Array.from(input.files));
  input.value = "";
}

const items = computed(() => buildThreadItems(messages.value));

const subtitle = computed(() => {
  if (!header.value) return "";
  if (header.value.isTyping) return "typing…";
  if (header.value.channelType === "channel") return `${header.value.memberCount} members`;
  return header.value.online ? "online" : "offline";
});

function receivedName(item: Extract<ThreadRenderItem, { kind: "message" }>): string | undefined {
  if (item.message.isMine || !item.first) return undefined;
  if (header.value?.channelType !== "channel") return undefined;
  return item.message.authorName ?? undefined;
}

function bodyText(body: string): string {
  return messageBodyToText(body);
}

function footer(item: Extract<ThreadRenderItem, { kind: "message" }>): string {
  const time = formatMessageTime(item.message.date);
  if (item.message.status === "failed") return `Failed · ${time}`;
  if (item.message.status === "pending") return `Sending… · ${time}`;
  return time;
}

function imageUrl(attachment: ThreadAttachment | null): string {
  if (!attachment) return "";
  if (attachment.localUrl) return attachment.localUrl;
  if (attachment.id == null) return "";
  const base = serverStore.baseUrl?.replace(/\/$/, "") ?? "";
  return `${base}/web/image/${attachment.id}`;
}

const photos = computed(() =>
  items.value
    .filter(
      (item): item is Extract<ThreadRenderItem, { kind: "message" }> =>
        item.kind === "message" && item.variant === "image",
    )
    .map((item) => imageUrl(item.attachment))
    .filter((url) => url.length > 0),
);

function openPhoto(url: string) {
  const list = photos.value;
  if (!list.length) return;
  const index = Math.max(0, list.indexOf(url));
  const browser = f7.photoBrowser.create({
    photos: list,
    type: "standalone",
    theme: "dark",
    toolbar: true,
    navbar: true,
  });
  browser.open(index);
}

function pageContentEl(): HTMLElement | null {
  return document.querySelector(".messenger-thread .page-content");
}

async function handleLoadOlder() {
  if (!hasMore.value || loadingOlder.value) return;
  const content = pageContentEl();
  const before = content?.scrollHeight ?? 0;
  await loadOlder();
  await nextTick();
  if (content) {
    const delta = content.scrollHeight - before;
    if (delta > 0) content.scrollTop += delta;
  }
}

function hideTabbar() {
  tabbarHidden.value = true;
}

function showTabbar() {
  tabbarHidden.value = false;
}
</script>
