<template>
  <div class="flex gap-2">
    <button
      v-for="tab in tabs"
      :key="tab.value"
      type="button"
      class="rounded-full px-3.5 py-1.5 text-[13px] font-[700] transition-colors"
      :class="model === tab.value ? 'bg-[#1f6df5] text-white' : 'bg-white text-[#657096]'"
      @click="model = tab.value"
    >
      {{ tab.label }}
    </button>
  </div>
</template>

<script setup lang="ts">
import type { ChannelTag } from "@aybsig/messenger";

const model = defineModel<ChannelTag>({ default: "all" });

const tabs: { value: ChannelTag; label: string }[] = [
  { value: "all", label: "All" },
  { value: "unread", label: "Unread" },
  { value: "group", label: "Groups" },
];
</script>
